"""Assistant reading notes written before opening case_panel_with_outcomes.csv."""
from pathlib import Path
import json,hashlib,datetime
B=Path(__file__).resolve().parent;out=B/'analysis_v1'
notes={
'C01':('direct','mixed','positive_opinion_and_partnership','Holiday revenue extrapolation and VCA Alexa partnership; multi-year growth/advertising template text. The asserted $400 billion operating-income increment is a suspect unit/magnitude requiring source review, not a verified fact. AAPL comparison and unrelated TripAdvisor promotion appear in body.'),
'C03':('direct_and_competitor_comparison','mixed','conflicting_horizons','Google smart-speaker sales catching up vs Amazon installed-base lead; another article predicts doubling over THREE YEARS, with Apple and bitcoin sections. Generic positive/negative averaging loses object, installed base vs flows, and horizon.'),
'C05':('market_roundup','past_price_recap','negative_then_rebound','FAANG drawdown and Friday rebound, mainly Facebook detail. Article summarizes prior returns, not an Amazon-specific surprise; includes market-wide context absent from pure company input.'),
'C08':('direct_and_market_roundup','stale_receipt','positive_historical','Both published Aug29 but received Sep4. Morgan Stanley target2500, market highs and new ad-video rumors; same historical market session across two articles. Multiple firms, navigation and promotion contaminate body.'),
'C09':('product_comparison_and_direct','mixed','uncertain_or_cancelled','Smart-speaker shopping advice is not a financial event. At-home diagnostics article says acquisition talks FELL APART and refers to summer exploration; headline exploring alone omits this. One additional job-advice title not body-read.'),
'C12':('direct_and_partner','mixed_future','positive_expectation_not_result','Qualcomm in-car integration reviews CES earlier in month; Amazon earnings preview explicitly says AFTER CLOSING BELL Jan31. Expected EPS/revenue and old guidance must not be read as realized earnings. Target ends before regular close; actual report is outside forecast interval.'),
'C13':('comparison_and_opinion','current_analysis','headline_more_negative_than_body','Headline says avoiding Amazon; body says professional money flows NEUTRAL and momo swings, with valuation argument. Two title variants are near duplicates. Positive outlook on Facebook is not Amazon positive sentiment.'),
'C14':('direct','event_update_with_history','denial_of_negative_claim','DHS/UK support company denials; full text repeats hacking accusations and prior Thu/Fri price losses. Negation and progression accusation→denial are essential; first disclosure of latest statement not authenticated.'),
'C15':('direct','recent_results_and_future_guidance','mixed_surprises','Q3 EPS5.75 beats3.08, revenue56.58 misses57.11, Q4 guidance66.5–72.5 below73.79 consensus, AWS growth46%. Must pair metric/period/actual vs consensus; strong growth alone misses disappointment. Prior after-close event and already-fallen price in article.'),
'C16':('direct','recent_but_first_time_unknown','positive_long_horizon','Alexa/Echo device refresh with multi-year market-growth forecasts and prior annual stock return. Exact original announcement time unclear; competitor mentions and generic positive language dominate.'),
'C19':('direct_and_competitor','mixed','opposing_perspectives','Amazon Pay interview recorded Nov26, published Nov28: familiarity advantage vs Apple/PayPal hardware advantage, not zero-sum. Graviton article starts with real AWS launch but argues present CPU performance/pricing disadvantage and later upside. Author hypothesis not established benchmark.'),
'C20':('direct_joint_announcement','new_disclosure_future_launch','positive_cooperation','Friday announcement enables Apple Music on Echo weekDec17; future launch does not make present disclosure old. Body repeats announcement and press release. Apple and Amazon are both objects, not competitors in this particular event.'),
'C21':('market_roundup','stale_receipt','negative_historical','Sept5/6 selloff articles acquired Sept19, 13–14day delay. Includes old Amazon two-percent loss, Apple Sept12 preview already past, market/trade context and large recommendation/navigation blocks. Third similar headline not body-read.')}
source=json.loads((out/'content_before_outcome.json').read_text());rows=[]
for c in source:
    fields=notes.get(c['case_id'],('none','none','none','No selected news in this window; content mechanism cannot be evaluated. This is part of the fixed target population, not a dropped sample.'))
    rows.append(dict(case_id=c['case_id'],target_relation=fields[0],temporal_role=fields[1],polarity=fields[2],note=fields[3],articles_read=len(c['articles']),read_limit_characters=5500,independent_gold=False))
p=out/'content_notes_before_reveal.json';assert not p.exists();p.write_text(json.dumps({'written_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'note':'Assistant knew aggregate and earlier project examples; outcome fields hidden in this reading copy, not independently blinded labeling.','cases':rows},ensure_ascii=False,indent=2)+'\n')
(out/'content_notes_seal.json').write_text(json.dumps({'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'cases':24,'article_excerpts_read':sum(x['articles_read'] for x in rows)},indent=2)+'\n')
print('Saved pre-reveal content notes:',len(rows),'cases')
